const headers = $input.first().json.headers || {};
const body = $input.first().json.body || $input.first().json;
const idempotencyKey = headers['x-idempotency-key'] || body.incident_id;
if (!idempotencyKey || !body.machine || !body.unit) {
  throw new Error('Payload de alerta invalido ou sem chave de idempotencia.');
}
const ticketId = `IPO-SAUDE-${Date.now().toString().slice(-6)}`;
const whatsappMessage = [
  `🚨 *[RMM SAÚDE IPOJUCA - ALERTA ${body.event_type}]*`,
  `🏥 *Unidade:* ${body.unit.name} (${body.unit.type})`,
  `📍 *Setor:* ${body.sector?.name || 'Geral'}`,
  `💻 *Equipamento:* ${body.machine.hostname} (${body.machine.ip_address})`,
  `⚠️ *Diagnóstico:* ${body.reason}`,
  `📊 *Métricas:* CPU ${body.metrics?.cpu_usage_pct}% | RAM ${body.metrics?.ram_usage_pct}% | HD ${body.metrics?.disk_usage_pct}%`,
  `🎫 *Chamado Aberto:* #${ticketId}`,
  `🔗 *Acesso 3D:* ${body.dashboard_url}`
].join('\n');
return [{ json: { ticket_id: ticketId, idempotency_key: idempotencyKey, whatsapp_text: whatsappMessage, raw_incident: body } }];
